package com.mycompany.greenbasket;
import java.sql.*;import java.math.BigDecimal;import java.util.*;
public class OrderDAO {
 public int createOrder(UserReg user,Map<Integer,Integer> cart,String address){ProductDAO pd=new ProductDAO();Connection c=null;try{c=DBConnection.getConnection();c.setAutoCommit(false);BigDecimal total=BigDecimal.ZERO;List<Product> ps=new ArrayList<>();for(var e:cart.entrySet()){Product p=pd.getById(e.getKey());if(p==null||p.getStock()<e.getValue())throw new SQLException("Invalid stock");ps.add(p);total=total.add(p.getPrice().multiply(BigDecimal.valueOf(e.getValue())));}int oid;try(PreparedStatement p=c.prepareStatement("INSERT INTO orders(user_id,total_amount,status,delivery_address) VALUES(?,?,'PLACED',?)",Statement.RETURN_GENERATED_KEYS)){p.setInt(1,user.getId());p.setBigDecimal(2,total);p.setString(3,address);p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){r.next();oid=r.getInt(1);}}try(PreparedStatement i=c.prepareStatement("INSERT INTO order_items(order_id,product_id,product_name,quantity,price) VALUES(?,?,?,?,?)");PreparedStatement s=c.prepareStatement("UPDATE products SET stock=stock-? WHERE id=? AND stock>=?")){for(Product p:ps){int qty=cart.get(p.getId());i.setInt(1,oid);i.setInt(2,p.getId());i.setString(3,p.getName());i.setInt(4,qty);i.setBigDecimal(5,p.getPrice());i.addBatch();s.setInt(1,qty);s.setInt(2,p.getId());s.setInt(3,qty);s.addBatch();}i.executeBatch();for(int x:s.executeBatch())if(x==0)throw new SQLException("Stock changed");}c.commit();return oid;}catch(Exception e){try{if(c!=null)c.rollback();}catch(Exception ignore){}e.printStackTrace();return 0;}finally{try{if(c!=null)c.close();}catch(Exception ignore){}}}
 public List<String[]> getOrdersForUser(int uid){List<String[]>l=new ArrayList<>();try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT id,total_amount,status,delivery_address,created_at FROM orders WHERE user_id=? ORDER BY id DESC")){p.setInt(1,uid);try(ResultSet r=p.executeQuery()){while(r.next())l.add(new String[]{r.getString(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5)});}}catch(Exception e){e.printStackTrace();}return l;}
 public List<String[]> getAllOrders(){List<String[]>l=new ArrayList<>();String q="SELECT o.id,u.name,o.total_amount,o.status,o.created_at FROM orders o JOIN userreg u ON u.id=o.user_id ORDER BY o.id DESC";try(Connection c=DBConnection.getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery(q)){while(r.next())l.add(new String[]{r.getString(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5)});}catch(Exception e){e.printStackTrace();}return l;}
}
